import{_ as l,l as h,o as t,c as o,v as e,p as n,x as i,d as b,i as c,S as E}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"条件期望","description":"","frontmatter":{"title":"条件期望","date":"2026-09-10T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/conditional-expectation-econ.md","filePath":"econ/conditional-expectation-econ.md","lastUpdated":1789023840000}'),d={name:"econ/conditional-expectation-econ.md"};function r(s,a,p,_,X,B){const m=h("Mermaid");return t(),o("div",null,[a[1]||(a[1]=e('<h1 id="条件期望" tabindex="-1">条件期望 <a class="header-anchor" href="#条件期望" aria-label="Permalink to &quot;条件期望&quot;">​</a></h1><div class="epigraph"><p>给定信息之后的最优均方预测，是对子 $\\sigma$-代数可测的那一次投影；塔性让「先粗后细」与直接一步相同。</p><footer>—— 据 Billingsley, Probability and Measure, 选章；Stokey, Lucas and Prescott, Recursive Methods 第 7–9 章整理</footer></div><p>上一课<a href="/econ/sigma-algebra">样本空间与 σ-代数</a>把信息写成子 \\(\\sigma\\)-代数 \\(\\mathcal{G}\\)。随机贝尔曼、欧拉方程、理性预期里出现的 \\(\\mathbb{E}_t\\)，不能再当成「把未知数换成均值」的口头禅。缺口是条件期望：\\(\\mathbb{E}[X\\mid\\mathcal{G}]\\) 是对 \\(\\mathcal{G}\\) 可测的可积随机变量，满足对一切 \\(G\\in\\mathcal{G}\\)，\\(\\int_G\\mathbb{E}[X\\mid\\mathcal{G}]\\,dP=\\int_G X\\,dP\\)。本课只补这一算子及其塔性、迭代法则；大数定律是下一课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>无信息时 \\(\\mathbb{E}[X]\\) 是一个数。有信息时预测仍是随机的：不同信息集给出不同数字。条件期望是唯一（a.s.）的 \\(\\mathcal{G}\\)-可测函数，在每个信息块上积分与 \\(X\\) 一致。有限分划上，它就是块内平均值。一般情形由 Radon–Nikodym 给出，本课不证。</p><p>均方意义：\\(\\mathbb{E}[X\\mid\\mathcal{G}]\\) 是 \\(X\\) 到 \\(\\mathcal{G}\\)-可测平方可积随机变量子空间的正交投影。正交性 \\(\\mathbb{E}[(X-\\mathbb{E}[X\\mid\\mathcal{G}])Z]=0\\) 对一切有界 \\(\\mathcal{G}\\)-可测 \\(Z\\) 成立——「残差与已知信息不相关」。理性预期均衡里的正交条件，就是这句话。</p><h3 id="条件期望不是「给定一个数-的公式」" tabindex="-1">条件期望不是「给定一个数 \\(x\\) 的公式」 <a class="header-anchor" href="#条件期望不是「给定一个数-的公式」" aria-label="Permalink to &quot;条件期望不是「给定一个数 $x$ 的公式」&quot;">​</a></h3><p>初等课本写 \\(\\mathbb{E}[Y\\mid X=x]\\) 为 \\(x\\) 的函数。严谨对象是随机变量 \\(\\mathbb{E}[Y\\mid\\sigma(X)]\\)，再在 \\(\\{X=x\\}\\) 上取值。连续分布下单点概率为零，「给定 \\(X=x\\)」要正则条件概率才有密度版。后课宏观写 \\(\\mathbb{E}[u&#39;(c_{t+1})\\mid\\mathcal{F}_t]\\)，对象是随机变量，不必先拿出密度。不要把条件期望缩回一条公式再对 \\(x\\) 求导，除非已经声明正则版本。</p><p><span class="marginnote">\\(\\mathbb{E}[X\\mid Y]\\) 是对 \\(\\sigma(Y)\\) 条件，不是「把 \\(Y\\) 当常数代入 \\(X\\) 的表达式」。\\(X\\) 与 \\(Y\\) 的联合结构决定投影，表达式代换会偷看不可测的部分。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>线性：\\(\\mathbb{E}[aX+bZ\\mid\\mathcal{G}]=a\\mathbb{E}[X\\mid\\mathcal{G}]+b\\mathbb{E}[Z\\mid\\mathcal{G}]\\)。已知的可提出：若 \\(Z\\) 对 \\(\\mathcal{G}\\) 可测且有界，\\(\\mathbb{E}[ZX\\mid\\mathcal{G}]=Z\\mathbb{E}[X\\mid\\mathcal{G}]\\)。塔性：\\(\\mathcal{H}\\subset\\mathcal{G}\\Rightarrow\\mathbb{E}[\\mathbb{E}[X\\mid\\mathcal{G}]\\mid\\mathcal{H}]=\\mathbb{E}[X\\mid\\mathcal{H}]\\)。迭代期望 \\(\\mathbb{E}[\\mathbb{E}[X\\mid\\mathcal{G}]]=\\mathbb{E}[X]\\) 是塔性取 \\(\\mathcal{H}\\) 平凡。Jensen：凸 \\(\\phi\\) 时 \\(\\phi(\\mathbb{E}[X\\mid\\mathcal{G}])\\le\\mathbb{E}[\\phi(X)\\mid\\mathcal{G}]\\)。后课风险厌恶、预防性储蓄用的条件 Jensen，在这里一次说清。</p><p>随机贝尔曼：\\(Tv(s,z)=\\max_a\\{F+\\beta\\mathbb{E}[v(s&#39;,z&#39;)\\mid s,z,a]\\}\\)。条件期望把未知的下期值压成对当前可测的函数，压缩论证才能在函数空间上继续。适应性策略：\\(a_t\\) 对 \\(\\mathcal{F}_t\\) 可测，于是不能对尚未实现的冲击取条件之外的依赖。</p>',12)),(t(),n(E,null,{default:i(()=>[c(m,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20X%5B%22%E5%8F%AF%E7%A7%AF%20X%22%5D%20--%3E%20PI%5B%22%E6%8A%95%E5%BD%B1%E5%88%B0%20G%20%E5%8F%AF%E6%B5%8B%E5%87%BD%E6%95%B0%22%5D%0A%20%20G%5B%22%E4%BF%A1%E6%81%AF%20G%22%5D%20--%3E%20PI%0A%20%20PI%20--%3E%20EX%5B%22E(X%20%E7%BB%99%E5%AE%9A%20G)%22%5D%0A%20%20EX%20--%3E%20TOWER%5B%22%E5%A1%94%E6%80%A7%EF%BC%9A%E5%85%88%E7%BB%86%E5%90%8E%E7%B2%97%E7%AD%89%E4%BA%8E%E7%9B%B4%E6%8E%A5%E7%B2%97%22%5D%0A%20%20EX%20--%3E%20DP%5B%22%E9%9A%8F%E6%9C%BA%E8%B4%9D%E5%B0%94%E6%9B%BC%E7%9A%84%E7%BB%AD%E5%80%BC%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[b(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>信息块内部，你不能再分辨 \\(\\omega\\)；最优的数是块上的平均（对 \\(P\\)）。换一块，平均数换一个。塔性说：先用细信息投影、再忘掉一部分，等于从未见过细信息——因为正交投影到套着的子空间可分解。宏观写 \\(\\mathbb{E}_t\\mathbb{E}_{t+1}X_{t+2}=\\mathbb{E}_t X_{t+2}\\)，就是滤波随时间变细时的塔性。</p><p>欧拉方程 \\(\\mathbb{E}_t[\\beta R_{t+1}u&#39;(c_{t+1})]=u&#39;(c_t)\\) 把一阶条件里未知的下期边际放进条件期望：对今天信息正交的残差不能再用来改善。这是 FONC 加投影，不是新的偏好理论。本课不把消费欧拉展开。</p><p><span class="marginnote">条件方差 \\(\\mathbb{E}[(X-\\mathbb{E}[X\\mid\\mathcal{G}])^2\\mid\\mathcal{G}]\\) 仍是随机变量。预防性储蓄关心的是这个对象的凸性，不是无条件方差。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不证 Radon–Nikodym，不讲鞅收敛定理全文（后课资产定价若需要再引）。不要把条件期望写成量化栏的 Itô 积分。也不进入 CAPM 的 beta 回归实证：正交投影与线性回归同族，但证券定价的假设不在金融栏这一课。下一课把无条件的样本平均与正态近似钉死，为加总与推断预备。</p><p>后课默认：\\(\\mathbb{E}_t\\) 是对当时信息的条件期望；随机欧拉、随机贝尔曼都按投影读写；塔性可直接用。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>\\(\\mathbb{E}[X\\mid\\mathcal{G}]\\) 是 \\(\\mathcal{G}\\)-可测投影，块上积分与 \\(X\\) 一致。</li><li>可提出已知量；塔性给出迭代期望。</li><li>Jensen 在条件里仍成立，供风险态度使用。</li><li>随机 DP 的续值是条件期望，不是随便写的均值。</li><li>下一课：<a href="/econ/lln-clt">大数定律与中心极限</a>。</li><li>出处：Billingsley, <em>Probability and Measure</em>；Stokey–Lucas–Prescott 第 7–9 章。</li></ul>',9))])}const G=l(d,[["render",r]]);export{A as __pageData,G as default};
